import { Text, View, type ViewProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { StatusGlyph } from "@/components/nyc-tron/ui/components/feedback/glyphs";

/** Props for {@linkcode ErrorMessage}. Drop-in for Nitro Forge's `StudioErrorMessageProps`. */
export interface ErrorMessageProps extends Omit<ViewProps,"children"> {
  /** Nothing renders without a message, so the row collapses. */
  message?:string;
  /**
   * Accepted so Forge's `surface="night"` call sites compile unchanged. It does
   * not pick colors: the danger token resolves from the nearest scheme scope,
   * so a message inside `NightScope` already takes the dark value.
   */
  surface?:"page"|"night";
  className?:string;
  messageClassName?:string;
  unstyled?:boolean;
}

/**
 * Inline error for a form or pane: what went wrong and how to recover, in one
 * or two sentences. Announced as an alert when it appears. The drawn "!" mark
 * keeps the state readable without color.
 */
export function ErrorMessage({
  message,surface:_surface,className,messageClassName,unstyled=false,...rest
}:ErrorMessageProps) {
  if(!message)return null;
  const styled=!unstyled;
  return (
    <View {...rest} {...{className:joinClasses("flex-row items-start",styled&&"gap-2",className)}}>
      <View {...{className:"pt-px"}}><StatusGlyph tone="danger"/></View>
      <Text role="alert" accessibilityLiveRegion="polite"
        {...{className:joinClasses("min-w-0 flex-1",styled&&"text-sm leading-5 text-danger",messageClassName)}}>
        {message}
      </Text>
    </View>
  );
}

import { View } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { space, radius, border } from "@/components/nyc-tron/ui/tokens";

/**
 * Status and close marks drawn with views, so they need no icon font, survive
 * forced colors (borders and backgrounds of a solid view stay visible) and
 * take the theme's tone tokens. Pass an `icon` to the owning component to use
 * the app's own icon set instead.
 */
export type StatusTone="info"|"success"|"danger"|"neutral";

// Fill and border in the same tone: forced colors drops backgrounds but
// keeps borders, so every part of a mark is drawn with a border too.
const FACE:Record<StatusTone,string>={
  info:"bg-info border-info",success:"bg-success border-success",
  danger:"bg-danger border-danger",neutral:"bg-text-muted border-text-muted",
};

/** 18pt disc with an "i", "!" or check cut out of it in the raised surface color. */
export function StatusGlyph({tone}:{tone:StatusTone}) {
  return (
    <View aria-hidden importantForAccessibility="no-hide-descendants"
      {...{className:joinClasses("h-[18px] w-[18px] items-center justify-center rounded-full border",FACE[tone])}}>
      {tone==="success" ? (
        // Two bars at right angles: the short stroke leads the long one.
        <View style={{width:9,height:6,marginTop:-space[0.5],transform:[{rotate:"-45deg"}]}}
          {...{className:"border-b-2 border-l-2 border-surface-raised"}}/>
      ) : (
        <View style={{alignItems:"center",gap:space[0.5],flexDirection:tone==="danger"?"column":"column-reverse"}}>
          <View style={{width:0,height:7,borderLeftWidth:border[2],borderRadius:radius[1]}} {...{className:"border-surface-raised"}}/>
          <View style={{width:2,height:2,borderWidth:border[1],borderRadius:radius[1]}} {...{className:"border-surface-raised"}}/>
        </View>
      )}
    </View>
  );
}

/** A 12pt cross made of two bars, colored by the caller's border token. */
export function CloseGlyph({className}:{className?:string}) {
  // Bars are top borders so forced colors keeps them.
  const bar=joinClasses("absolute h-0 w-3 border-t-2",className??"border-text-muted");
  return (
    <View aria-hidden importantForAccessibility="no-hide-descendants"
      style={{width:12,height:12,alignItems:"center",justifyContent:"center"}}>
      <View style={{transform:[{rotate:"45deg"}]}} {...{className:bar}}/>
      <View style={{transform:[{rotate:"-45deg"}]}} {...{className:bar}}/>
    </View>
  );
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

