  11: 11,
  12: 12,
  13: 13,
  14: 14,
  15: 15,
  16: 16,
  17: 17,
} as const;

/** Line height steps in px, keyed by value. */
export const leading = {
  14: 14,
  16: 16,
} as const;

/** Border width steps in px, keyed by value (`border[1.5]`). */
export const border = {
  0: 0,
  1: 1,
  1.5: 1.5,
  2: 2,
  3: 3,
  4: 4,
  8: 8,
