/** Opacity steps keyed by percent (`opacity[45]` is 0.45). 0 and 1 are not tokens. */
export const opacity = {
  30: 0.3,
  35: 0.35,
  40: 0.4,
  45: 0.45,
  50: 0.5,
  55: 0.55,
  60: 0.6,
  70: 0.7,
  90: 0.9,
} as const;

/** Black overlay colours keyed by alpha percent. */
export const scrim = {
  12: "rgba(0,0,0,0.12)",
  18: "rgba(0,0,0,0.18)",
  25: "rgba(0,0,0,0.25)",
  50: "rgba(0,0,0,0.5)",
} as const;

/** Box shadows. `elevation[0]` is none. */
export const elevation = {
  0: "none",
  1: "0 1px 3px rgba(0,0,0,0.25)",
  2: "0 4px 12px rgba(0,0,0,0.18)",
} as const;

/** Fixed sizes. `size.touch` is the 44 px minimum touch target. */
export const size = {
  touch: 44,
} as const;
